(50801, 'buy', 'residential', 'Apartment', 2, 2, 1150, 9800000, 'lucknow', 'gomti-nagar', NULL, 'Semi-Furnished', 'Owner', 'Ready to Move', 6, 14, 'East', 4, '["Lift","Power Backup","Covered Parking","24x7 Security","Kids Play Area"]', 'Ritika Srivastava', 1, 'active', 205, '2026-10-19T08:24:31Z', 0, 2, NULL, 'Bright east-facing 2 BHK on the 6th floor, a short walk from Gomti Nagar’s markets. Modular kitchen, two balconies and covered parking.'),
(50802, 'buy', 'residential', 'Apartment', 3, 3, 1600, 11200000, 'lucknow', 'indira-nagar', NULL, 'Semi-Furnished', 'Agent', 'Ready to Move', 3, 10, 'North-East', 7, '["Lift","Power Backup","Gymnasium","Clubhouse","Covered Parking","CCTV Surveillance"]', 'Amit Verma', 1, 'active', 180, '2026-10-13T08:24:31Z', 0, 2, NULL, 'Spacious 3 BHK with a large living room and a study corner, in a gated society close to schools and the Indira Nagar metro station.'),
(50803, 'rent', 'residential', 'Apartment', 2, 2, 1000, 28000, 'lucknow', 'hazratganj', NULL, 'Furnished', 'Owner', 'Ready to Move', 2, 5, 'North', 10, '["Power Backup","24x7 Security","Lift"]', 'Saba Rizvi', 0, 'active', 230, '2026-10-17T08:24:31Z', 0, 2, NULL, 'Fully furnished 2 BHK in the heart of Hazratganj — walk to cafés, offices and the metro. Suits a small family or working professionals.'),
(50804, 'rent', 'residential', 'Apartment', 1, 1, 560, 9500, 'lucknow', 'aliganj', NULL, 'Unfurnished', 'Owner', 'Ready to Move', 1, 4, 'West', 12, '["Power Backup","Covered Parking"]', 'Pankaj Tiwari', 1, 'active', 160, '2026-10-10T08:24:31Z', 0, 2, NULL, 'Compact 1 BHK in a quiet lane of Aliganj with a separate entrance and two-wheeler parking. Close to Kapoorthala market.');
