INSERT INTO forum_questions (id, author, city_slug, title, body, created_at) VALUES
(1, 'Rohit S.', 'pune', 'Is Hinjewadi still a good bet for a 2 BHK in 2026?', 'Planning to buy for self-use, I work in Phase 1. Worried about traffic and water supply. Any residents here?', '2026-09-12T08:24:31Z'),
(2, 'Farah N.', 'mumbai', 'Carpet area vs built-up — how much difference is normal?', 'A resale flat is advertised as 1,000 sq.ft built-up. What carpet area should I expect?', '2026-09-19T08:24:31Z'),
(3, 'Sanjay T.', 'bengaluru', 'What security deposit is normal for rentals in Whitefield?', 'Landlord is asking for 8 months deposit for a 2 BHK. Is that standard?', '2026-09-26T08:24:31Z'),
(4, 'Kiran D.', 'gurugram', 'Under-construction project delayed by 2 years — what are my options?', 'Builder keeps postponing possession. The RERA date has passed.', '2026-10-03T08:24:31Z');
INSERT INTO forum_answers (question_id, author, body, created_at) VALUES
(1, 'Meghna K.', 'Traffic on the main road is bad at peak hours, but Phase 2 and 3 societies are close to offices. Check water supply hours with the society before buying.', '2026-09-14T08:24:31Z'),
(1, 'Anil P.', 'Prices grew steadily here. If you work in Phase 1, Wakad is also worth checking for better social infrastructure.', '2026-09-15T08:24:31Z'),
(2, 'Vivek R.', 'Typically carpet is 70–80% of built-up in Mumbai. Ask for the carpet area in writing and compare price per sq.ft of carpet.', '2026-09-21T08:24:31Z'),
(3, 'Divya M.', 'Bengaluru deposits are high, but 5–6 months is more common now. You can negotiate, especially for longer lock-ins.', '2026-09-28T08:24:31Z'),
(4, 'Advocate Mehra', 'You can file a complaint with Haryana RERA for interest on delayed possession or a full refund with interest. Keep all payment receipts and the builder-buyer agreement ready.', '2026-10-05T08:24:31Z');
